-- Citora frontend: read-only service identity for the Snowflake SQL API.
-- Run once as ACCOUNTADMIN (or equivalent roles with user/role/grant privileges).

USE ROLE SECURITYADMIN;

CREATE ROLE IF NOT EXISTS CITORA_FRONTEND_READER
    COMMENT = 'Read-only access used by the Citora web application';

GRANT ROLE CITORA_FRONTEND_READER TO ROLE SYSADMIN;

CREATE USER IF NOT EXISTS CITORA_FRONTEND_SERVICE
    TYPE = SERVICE
    LOGIN_NAME = 'CITORA_FRONTEND_SERVICE'
    DEFAULT_ROLE = CITORA_FRONTEND_READER
    DEFAULT_WAREHOUSE = CITORA_TRANSFORMING_WH
    DEFAULT_NAMESPACE = CITORA.ANALYTICS
    COMMENT = 'Service identity used by the Citora web application';

ALTER USER CITORA_FRONTEND_SERVICE SET
    RSA_PUBLIC_KEY = '';

GRANT ROLE CITORA_FRONTEND_READER TO USER CITORA_FRONTEND_SERVICE;

USE ROLE SYSADMIN;

GRANT USAGE ON WAREHOUSE CITORA_TRANSFORMING_WH
    TO ROLE CITORA_FRONTEND_READER;

GRANT USAGE ON DATABASE CITORA
    TO ROLE CITORA_FRONTEND_READER;

GRANT USAGE ON SCHEMA CITORA.ANALYTICS
    TO ROLE CITORA_FRONTEND_READER;

GRANT SELECT ON TABLE CITORA.ANALYTICS.FCT_REPORTING_METRICS
    TO ROLE CITORA_FRONTEND_READER;

-- Verification. RSA_PUBLIC_KEY_FP must be populated.
USE ROLE SECURITYADMIN;
DESCRIBE USER CITORA_FRONTEND_SERVICE;

